import { LotteryTypePage } from '../../../pages/lottery-type/lottery-type.page';
import { Logger } from '../../logger';

const logger = new Logger();

/**
 * Only codes generated by the test data factory start with "AT". Cleanup never touches anything
 * else, so a test that submits an existing (real) code can never delete real data.
 */
const AUTOMATION_CODE = /^AT/;

/**
 * Best-effort delete of the lottery types a test created (afterEach).
 * Uses the row menu -> Delete; skips codes that are not listed (never saved / already deleted).
 */
export async function cleanupLotteryTypes(lotteryTypePage: LotteryTypePage, codes: string[]): Promise<void> {
  const page = lotteryTypePage.page;
  const ownCodes = [...new Set(codes.map((c) => c.trim()))].filter((c) => AUTOMATION_CODE.test(c));
  if (ownCodes.length === 0) return;
  try {
    if (await page.getByRole('dialog').isVisible().catch(() => false)) {
      await page.keyboard.press('Escape').catch(() => {});
    }
    if (!page.url().includes(LotteryTypePage.PATH)) {
      await page.goto(LotteryTypePage.PATH);
    } else {
      await page.reload();
    }
    await lotteryTypePage.verifyPageLoaded();
  } catch {
    logger.warn('⚠️ Cleanup could not reopen the Lottery Type page');
    return;
  }
  for (const code of ownCodes) {
    try {
      if (!(await lotteryTypePage.lotteryTypeExists(code, 3000))) continue;
      await lotteryTypePage.deleteLotteryType(code);
      logger.info(`🧹 Cleaned up lottery type: ${code}`);
    } catch {
      logger.warn(`⚠️ Could not clean up lottery type: ${code}`);
    }
  }
}

export async function cleanupLotteryType(lotteryTypePage: LotteryTypePage, code: string): Promise<void> {
  await cleanupLotteryTypes(lotteryTypePage, [code]);
}
